import "core-js/modules/es.array.push.js";
import DeleteRetirereason from "@/components/Asset/Popups/DeleteRetirereason.vue";
import AddRetirereason from "@/components/Asset/Popups/AddRetirereason.vue";
import SnackBar from "@/components/SnackBar.vue";
import { asset_retire } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    SnackBar,
    DeleteRetirereason,
    AddRetirereason
  },
  emits: ['backAction'],
  data() {
    return {
      fixed: false,
      SnackBarComponent: {},
      componentCheck: 0,
      suppliereRecords: [],
      tableLoading: false,
      retiredeletion: false,
      retireitems: {},
      suppliereHeaders: [{
        title: "Reason",
        key: "retire_reason",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      retireAddition: false,
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      windowHeight: 0
    };
  },
  async mounted() {
    this.updateWindowHeight();
    window.addEventListener('resize', this.updateWindowHeight);
    this.fetch_assetretire();
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateWindowHeight);
  },
  computed: {
    totalCount() {
      return this.suppliereRecords.length;
    },
    pageCount() {
      return Math.ceil(this.suppliereRecords.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    add_reasonretire() {
      this.componentCheck = 2;
      this.retireAddition = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.retiredeletion = false;
      this.retireAddition = false;
      this.fetch_assetretire();
    },
    open_deleteDailog(item) {
      this.retireitems = item;
      this.componentCheck = 1;
      this.retiredeletion = true;
    },
    async fetch_assetretire() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_retire, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "LIST_RETIRE_REASON"
          }
        }));
        var response = JSON.parse(result.data.asset_retire);
        this.suppliereRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.suppliereRecords = response.data;
          this.tableLoading = false;
          this.updatePageItems();
        } else {
          this.suppliereRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.suppliereRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    updatePageItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      this.paginatedItems = this.suppliereRecords.slice(start, end);
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 310; // Adjust for header and footer
    }
  }
};
